package handlers

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httptest"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// The tests never call NASA. Each points the handler at an httptest server that
// answers a few generated bytes; no image file exists in the repo.

// globeTileBytes is the fake picture: a few bytes the handler must pass through
// untouched.
var globeTileBytes = []byte("\xff\xd8\xff\xe0fake-globe-tile-bytes\xff\xd9")

// fakeGIBS is a counting stand in for the NASA host.
type fakeGIBS struct {
	srv   *httptest.Server
	calls atomic.Int64
	mu    sync.Mutex
	paths []string
	uas   []string
	// answer lets a test change what the upstream says.
	answer func(w http.ResponseWriter, r *http.Request)
}

func newFakeGIBS(t *testing.T) *fakeGIBS {
	t.Helper()
	f := &fakeGIBS{}
	f.answer = func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "image/jpeg")
		_, _ = w.Write(globeTileBytes)
	}
	f.srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		f.calls.Add(1)
		f.mu.Lock()
		f.paths = append(f.paths, r.URL.Path)
		f.uas = append(f.uas, r.Header.Get("User-Agent"))
		answer := f.answer
		f.mu.Unlock()
		// A small pause so concurrent callers really overlap.
		time.Sleep(20 * time.Millisecond)
		answer(w, r)
	}))
	t.Cleanup(f.srv.Close)
	return f
}

func (f *fakeGIBS) set(answer func(w http.ResponseWriter, r *http.Request)) {
	f.mu.Lock()
	f.answer = answer
	f.mu.Unlock()
}

func globeServe(h http.Handler, path string) *httptest.ResponseRecorder {
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
	return rec
}

func TestGlobeTilePaths(t *testing.T) {
	paths := GlobeTilePaths()
	if len(paths) != 85 {
		t.Fatalf("GlobeTilePaths has %d entries, want 85", len(paths))
	}
	shape := regexp.MustCompile(`^/globe/tiles/([0-3])/([0-9]+)/([0-9]+)\.jpg$`)
	perZoom := map[string]int{}
	seen := map[string]bool{}
	for _, p := range paths {
		m := shape.FindStringSubmatch(p)
		if m == nil {
			t.Fatalf("%q does not match the tile path shape", p)
		}
		if seen[p] {
			t.Fatalf("%q is listed twice", p)
		}
		seen[p] = true
		perZoom[m[1]]++
		var z, y, x int
		if _, err := fmt.Sscanf(m[1]+" "+m[2]+" "+m[3], "%d %d %d", &z, &y, &x); err != nil {
			t.Fatalf("parsing %q: %v", p, err)
		}
		if y >= 1<<z || x >= 1<<z {
			t.Fatalf("%q has an index out of range for zoom %d", p, z)
		}
	}
	want := map[string]int{"0": 1, "1": 4, "2": 16, "3": 64}
	for z, n := range want {
		if perZoom[z] != n {
			t.Errorf("zoom %s has %d paths, want %d", z, perZoom[z], n)
		}
	}

	g := NewGlobeTiles(GlobeTilesConfig{Upstream: "http://127.0.0.1:1"})
	for _, p := range paths {
		if _, ok := g.Handler(p); !ok {
			t.Errorf("Handler(%q) = false, want true for a listed path", p)
		}
	}
	for _, p := range []string{
		"/globe/tiles/4/0/0.jpg",
		"/globe/tiles/1/2/0.jpg",
		"/globe/tiles/1/0/2.jpg",
		"/globe/tiles/0/0/0.png",
		"/globe/tiles/0/0/0.jpeg",
		"/globe/tiles/0/0/0.jpg/",
		"/globe/tiles/00/0/0.jpg",
		"/globe/tiles/0/0/../0.jpg",
		"/globe/tiles",
		"",
	} {
		if h, ok := g.Handler(p); ok || h != nil {
			t.Errorf("Handler(%q) = true, want false for a path outside the list", p)
		}
	}
}

func TestGlobeTileFetchedOnce(t *testing.T) {
	up := newFakeGIBS(t)
	g := NewGlobeTiles(GlobeTilesConfig{Upstream: up.srv.URL + "/base", UserAgent: "Pinalert/1.0 (+test)"})
	h, ok := g.Handler("/globe/tiles/2/1/3.jpg")
	if !ok {
		t.Fatal("no handler for a listed path")
	}

	const callers = 20
	recs := make([]*httptest.ResponseRecorder, callers)
	var wg sync.WaitGroup
	for i := 0; i < callers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			recs[i] = globeServe(h, "/globe/tiles/2/1/3.jpg")
		}()
	}
	wg.Wait()

	for i, rec := range recs {
		if rec.Code != http.StatusOK {
			t.Fatalf("caller %d got %d, want 200", i, rec.Code)
		}
		if !bytes.Equal(rec.Body.Bytes(), globeTileBytes) {
			t.Fatalf("caller %d got different bytes", i)
		}
	}
	if n := up.calls.Load(); n != 1 {
		t.Fatalf("the upstream saw %d requests, want exactly 1", n)
	}
	// A later request is answered from memory too.
	if rec := globeServe(h, "/globe/tiles/2/1/3.jpg"); rec.Code != http.StatusOK {
		t.Fatalf("a repeat request got %d, want 200", rec.Code)
	}
	if n := up.calls.Load(); n != 1 {
		t.Fatalf("a repeat request reached the upstream (%d requests)", n)
	}
	// Row y is 1 and column x is 3: the upstream address is {z}/{y}/{x}.jpeg.
	if got, want := up.paths[0], "/base/2/1/3.jpeg"; got != want {
		t.Errorf("the upstream path = %q, want %q", got, want)
	}
	if got, want := up.uas[0], "Pinalert/1.0 (+test)"; got != want {
		t.Errorf("the upstream User-Agent = %q, want %q", got, want)
	}
}

func TestGlobeTileRefusesBadUpstream(t *testing.T) {
	cases := []struct {
		name   string
		answer func(w http.ResponseWriter, r *http.Request)
	}{
		{"redirect", func(w http.ResponseWriter, r *http.Request) {
			http.Redirect(w, r, "http://127.0.0.1:1/elsewhere.jpeg", http.StatusFound)
		}},
		{"not a jpeg", func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Type", "text/html")
			_, _ = w.Write([]byte("<html>no</html>"))
		}},
		{"oversize", func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Type", "image/jpeg")
			_, _ = w.Write(bytes.Repeat([]byte("x"), GlobeTileMaxBytes+1))
		}},
		{"server error", func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Type", "image/jpeg")
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write(globeTileBytes)
		}},
		{"empty body", func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Type", "image/jpeg")
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			up := newFakeGIBS(t)
			up.set(tc.answer)
			g := NewGlobeTiles(GlobeTilesConfig{Upstream: up.srv.URL})
			h, _ := g.Handler("/globe/tiles/0/0/0.jpg")
			rec := globeServe(h, "/globe/tiles/0/0/0.jpg")
			if rec.Code != http.StatusNotFound {
				t.Fatalf("got %d, want 404", rec.Code)
			}
			if rec.Header().Get("Set-Cookie") != "" {
				t.Fatalf("a refusal set a cookie")
			}
			if _, cached := g.bodies.Load("/globe/tiles/0/0/0.jpg"); cached {
				t.Fatalf("a refused answer was kept in memory")
			}
		})
	}
}

func TestGlobeTileOversizeAtTheLimitIsKept(t *testing.T) {
	up := newFakeGIBS(t)
	up.set(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "image/jpeg; charset=binary")
		_, _ = w.Write(bytes.Repeat([]byte("x"), GlobeTileMaxBytes))
	})
	g := NewGlobeTiles(GlobeTilesConfig{Upstream: up.srv.URL})
	h, _ := g.Handler("/globe/tiles/0/0/0.jpg")
	if rec := globeServe(h, "/globe/tiles/0/0/0.jpg"); rec.Code != http.StatusOK {
		t.Fatalf("a body of exactly the limit got %d, want 200", rec.Code)
	}
}

func TestGlobeTileFailureRemembered(t *testing.T) {
	up := newFakeGIBS(t)
	up.set(func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusInternalServerError) })
	g := NewGlobeTiles(GlobeTilesConfig{Upstream: up.srv.URL})
	now := time.Date(2026, 10, 28, 12, 0, 0, 0, time.UTC)
	g.now = func() time.Time { return now }
	h, _ := g.Handler("/globe/tiles/1/0/1.jpg")

	if rec := globeServe(h, "/globe/tiles/1/0/1.jpg"); rec.Code != http.StatusNotFound {
		t.Fatalf("first request got %d, want 404", rec.Code)
	}
	if n := up.calls.Load(); n != 1 {
		t.Fatalf("after the first request the upstream saw %d, want 1", n)
	}

	now = now.Add(59 * time.Second)
	if rec := globeServe(h, "/globe/tiles/1/0/1.jpg"); rec.Code != http.StatusNotFound {
		t.Fatalf("second request got %d, want 404", rec.Code)
	}
	if n := up.calls.Load(); n != 1 {
		t.Fatalf("within 60 seconds the upstream was called again (%d)", n)
	}

	// The upstream recovers; after the memory runs out the tile is fetched.
	up.set(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "image/jpeg")
		_, _ = w.Write(globeTileBytes)
	})
	now = now.Add(2 * time.Second)
	if rec := globeServe(h, "/globe/tiles/1/0/1.jpg"); rec.Code != http.StatusOK {
		t.Fatalf("after 60 seconds got %d, want 200", rec.Code)
	}
	if n := up.calls.Load(); n != 2 {
		t.Fatalf("after 60 seconds the upstream saw %d requests, want 2", n)
	}
}

func TestGlobeTileHeaders(t *testing.T) {
	up := newFakeGIBS(t)
	up.set(func(w http.ResponseWriter, _ *http.Request) {
		// An upstream that tries to set a cookie must not pass it on.
		w.Header().Set("Set-Cookie", "upstream=1")
		w.Header().Set("Content-Type", "image/jpeg")
		_, _ = w.Write(globeTileBytes)
	})
	g := NewGlobeTiles(GlobeTilesConfig{Upstream: up.srv.URL})
	h, _ := g.Handler("/globe/tiles/0/0/0.jpg")
	rec := globeServe(h, "/globe/tiles/0/0/0.jpg")
	if rec.Code != http.StatusOK {
		t.Fatalf("got %d, want 200", rec.Code)
	}
	for k, want := range map[string]string{
		"Content-Type":           "image/jpeg",
		"Cache-Control":          "public, max-age=2592000",
		"X-Content-Type-Options": "nosniff",
	} {
		if got := rec.Header().Get(k); got != want {
			t.Errorf("%s = %q, want %q", k, got, want)
		}
	}
	if got := rec.Header().Values("Set-Cookie"); len(got) != 0 {
		t.Errorf("Set-Cookie = %v, want none", got)
	}
	if strings.Contains(GlobeCacheControl, "no-store") {
		t.Errorf("GlobeCacheControl must not carry no-store")
	}
}

func TestGlobeTileUpstreamIsTheNASAConstant(t *testing.T) {
	g := NewGlobeTiles(GlobeTilesConfig{})
	if g.upstream != globeUpstreamBase {
		t.Fatalf("an empty Upstream gave %q, want the NASA constant", g.upstream)
	}
	if !strings.HasPrefix(globeUpstreamBase, "https://gibs.earthdata.nasa.gov/") {
		t.Fatalf("the constant upstream is not https on the GIBS host: %q", globeUpstreamBase)
	}
}
